async function bounded(promise,ms=6000){let timer;try{return await Promise.race([promise,new Promise((_,reject)=>{timer=setTimeout(()=>reject(Error('Owned close deadline')),ms);})]);}finally{clearTimeout(timer);}}
async function cli(tokenFile,args){return new Promise((resolve,reject)=>{const child=spawn(process.execPath,[path.join(repo,'packages/cli/dist/index.js'),'--json','--url',baseUrl,'--token-file',tokenFile,...args],{env:process.env,stdio:['ignore','pipe','pipe']});let out='';const timeout=setTimeout(()=>child.kill('SIGTERM'),15000);child.stdout.on('data',x=>out+=x);child.stderr.resume();child.on('error',reject);child.on('close',(code,signal)=>{clearTimeout(timeout);try{resolve({code,signal,value:JSON.parse(out)});}catch{reject(Error('Invalid owned CLI output'));}});});}
