 return {async call(name,args){const response=await sdk.callTool({name,arguments:mode==='wrapped'?{input:args}:args},undefined,opts);if(response.isError){const error=Error('MCP operation refused');Object.assign(error,{code:response.structuredContent.error.code,details:response.structuredContent.error.details,publicMessage:response.structuredContent.error.message});throw error;}return response.structuredContent.result;},async close(){await sdk.close();await transport.close();const exit=await bounded(closePromise);assert.deepEqual(exit,{code:0,signal:null});assert.deepEqual(signals,[]);active.delete(record);evidence.transports.push({mode,tool_count:9,exit,requested_signals:signals});}};
